export const PUBLIC_CRISIS_REQUIRED_SOURCES = Object.freeze({decision:Object.freeze(['01','02','18','19']),guarantee:Object.freeze(['03','05','21']),financing:Object.freeze(['06','07','10','11']),monitoring:Object.freeze(['05','08','09','13','14'])});
export function publicCrisisSvg(lang,kind){
 if(typeof lang!=='string'||!['fr','en'].includes(lang)||typeof kind!=='string'||!PUBLIC_CRISIS_KINDS.includes(kind))throw new TypeError('Invalid public-crisis figure variant');
 return FIGURES[`${kind}-${lang}`];
}
export function publicCrisisReferences(kind,sources){
 if(typeof kind!=='string'||!PUBLIC_CRISIS_KINDS.includes(kind)||typeof sources!=='string')throw new TypeError('Invalid public-crisis figure references');
 const references=sources.trim()?sources.trim().split(/\s+/u):[],required=PUBLIC_CRISIS_REQUIRED_SOURCES[kind];
 if(references.length!==required.length||new Set(references).size!==references.length||references.some(id=>!required.includes(id)))throw new TypeError('Incomplete or invalid public-crisis source references');
 return Object.freeze(references);
}
export function publicCrisisInlineSvg(lang,kind){
 // Controlled static originals only; no user-controlled markup reaches set:html.
 let svg=publicCrisisSvg(lang,kind).replace(/^<svg /u,'<svg style="width:100%;height:auto" ');
 // Four exact baselines per language: move each crowded card's title/body together.
 // Words, font metrics, panel geometry and the original static source remain unchanged.
 if(kind==='monitoring')for(const[from,to]of [[559,554],[594,589],[816,811],[851,846]]){
  const before=`<text x="786" y="${from}"`,after=`<text x="786" y="${to}"`;
  if(svg.split(before).length!==2)throw new TypeError('Expected unique static monitoring label');
  svg=svg.replace(before,after);
 }
 if(kind==='financing'){
  const before=lang==='fr'?'Dernier constat vérifié : 30 juin 2026.':'Last verified observation: 30 June 2026.';
  const after=lang==='fr'?'Dernier constat comptable : 30 juin 2026.':'Latest accounts checked: 30 June 2026.';
  if(svg.split(before).length!==2)throw new TypeError('Expected unique static accounting label');
  svg=svg.replace(before,after);
 }
 return svg;
}
